// 1. Obtener los datos extraídos de la IA
const aiResponse = $('AI Extraer Datos Factura').first().json.response;
let d;
try {
  d = JSON.parse(aiResponse.match(/\{[\s\S]*\}/)[0]);
} catch(e) {
  throw new Error('Error IA: No se pudo leer el JSON de Ollama');
}

// 2. Limpiar caracteres y preparar la nueva fila
const esc = (s) => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

// Función para asegurar formato DD-MM-AAAA
const formatDate = (dateStr) => {
  if (!dateStr) return '';
  const cleanDate = String(dateStr).split('T')[0].trim();
  const parts = cleanDate.split(/[-/.]/);
  if (parts.length === 3) {
    if (parts[0].length === 4) { // YYYY-MM-DD
      return `${parts[2].padStart(2, '0')}-${parts[1].padStart(2, '0')}-${parts[0]}`;
    }
    if (parts[2].length === 4) { // DD-MM-YYYY
      return `${parts[0].padStart(2, '0')}-${parts[1].padStart(2, '0')}-${parts[2]}`;
    }
  }
  return dateStr;
};

const f_numero = esc(d.factura_numero);
const f_fecha = formatDate(d.factura_fecha);

const dirE = [d.empresa_direccion, d.empresa_cp, d.empresa_ciudad, d.empresa_provincia].filter(Boolean).join(', ');
const dirC = [d.cliente_direccion, d.cliente_cp, d.cliente_ciudad, d.cliente_provincia].filter(Boolean).join(', ');
const desc = (d.lineas || []).map(l => l.descripcion).filter(Boolean).join(' | ') || 'Factura';

// ORDEN: Nº Factura (1), Fecha (2)
let newRow = `<Row><Cell><Data ss:Type="String">${f_numero}</Data></Cell><Cell><Data ss:Type="String">${f_fecha}</Data></Cell><Cell><Data ss:Type="String">${esc(d.empresa_nombre)}</Data></Cell><Cell><Data ss:Type="String">${esc(d.empresa_cif)}</Data></Cell><Cell><Data ss:Type="String">${esc(dirE)}</Data></Cell><Cell><Data ss:Type="String">${esc(d.empresa_telefono)}</Data></Cell><Cell><Data ss:Type="String">${esc(d.cliente_nombre)}</Data></Cell><Cell><Data ss:Type="String">${esc(d.cliente_cif)}</Data></Cell><Cell><Data ss:Type="String">${esc(dirC)}</Data></Cell><Cell><Data ss:Type="String">${esc(desc)}</Data></Cell><Cell><Data ss:Type="Number">1</Data></Cell><Cell><Data ss:Type="Number">${parseFloat(d.base_imponible)||0}</Data></Cell><Cell><Data ss:Type="Number">${parseFloat(d.base_imponible)||0}</Data></Cell><Cell><Data ss:Type="Number">${parseFloat(d.iva_porcentaje)||0}</Data></Cell><Cell><Data ss:Type="Number">${parseFloat(d.base_imponible)||0}</Data></Cell><Cell><Data ss:Type="Number">${parseFloat(d.cuota_iva)||0}</Data></Cell><Cell><Data ss:Type="Number">${parseFloat(d.total_factura)||0}</Data></Cell><Cell><Data ss:Type="String">${esc(d.forma_pago)}</Data></Cell><Cell><Data ss:Type="String">${esc(d.vencimiento)}</Data></Cell></Row>`;

// 3. Extraer de manera segura el Excel existente
let xml = '';
const items = $input.all();
if (items.length > 0 && items[0].binary && items[0].binary.data) {
  try {
    const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
    if (buffer) xml = buffer.toString('utf-8');
  } catch (err) {
    if (items[0].binary.data.data) xml = Buffer.from(items[0].binary.data.data, 'base64').toString('utf-8');
  }
}

// 4. Inyectar fila o crear estructura
const tableEndRegex = /(<\/(?:ss:)?Table\s*>)/i;

if (xml && tableEndRegex.test(xml)) {
  xml = xml.replace(tableEndRegex, newRow + '\n$1');
} else {
  const h = '<Row ss:Height="30"><Cell ss:StyleID="header"><Data ss:Type="String">Nº Factura</Data></Cell><Cell ss:StyleID="header"><Data ss:Type="String">Fecha</Data></Cell><Cell ss:StyleID="header"><Data ss:Type="String">Empresa</Data></Cell><Cell ss:StyleID="header"><Data ss:Type="String">CIF Empresa</Data></Cell><Cell ss:StyleID="header"><Data ss:Type="String">Dir Empresa</Data></Cell><Cell ss:StyleID="header"><Data ss:Type="String">Tel</Data></Cell><Cell ss:StyleID="header"><Data ss:Type="String">Cliente</Data></Cell><Cell ss:StyleID="header"><Data ss:Type="String">CIF Cliente</Data></Cell><Cell ss:StyleID="header"><Data ss:Type="String">Dir Cliente</Data></Cell><Cell ss:StyleID="header"><Data ss:Type="String">Desc</Data></Cell><Cell ss:StyleID="header"><Data ss:Type="String">Cant</Data></Cell><Cell ss:StyleID="header"><Data ss:Type="String">Precio</Data></Cell><Cell ss:StyleID="header"><Data ss:Type="String">Imp</Data></Cell><Cell ss:StyleID="header"><Data ss:Type="String">%IVA</Data></Cell><Cell ss:StyleID="header"><Data ss:Type="String">Base</Data></Cell><Cell ss:StyleID="header"><Data ss:Type="String">Cuota</Data></Cell><Cell ss:StyleID="header"><Data ss:Type="String">Total</Data></Cell><Cell ss:StyleID="header"><Data ss:Type="String">Pago</Data></Cell><Cell ss:StyleID="header"><Data ss:Type="String">Venc</Data></Cell></Row>';
  xml = `<?xml version="1.0" encoding="UTF-8"?><?mso-application progid="Excel.Sheet"?><Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet" xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet"><Styles><Style ss:ID="Default"><Font ss:FontName="Calibri" ss:Size="11"/></Style><Style ss:ID="header"><Font ss:Bold="1" ss:Color="#FFFFFF" ss:FontName="Calibri" ss:Size="11"/><Interior ss:Color="#1F4E79" ss:Pattern="Solid"/><Alignment ss:Horizontal="Center" ss:Vertical="Center" ss:WrapText="1"/></Style></Styles><Worksheet ss:Name="Facturas"><Table><Column ss:Width="100"/><Column ss:Width="90"/><Column ss:Width="180"/><Column ss:Width="110"/><Column ss:Width="250"/><Column ss:Width="100"/><Column ss:Width="180"/><Column ss:Width="110"/><Column ss:Width="250"/><Column ss:Width="200"/><Column ss:Width="50"/><Column ss:Width="80"/><Column ss:Width="80"/><Column ss:Width="50"/><Column ss:Width="80"/><Column ss:Width="80"/><Column ss:Width="80"/><Column ss:Width="100"/><Column ss:Width="90"/>${h}${newRow}</Table></Worksheet></Workbook>`;
}

const buffer = Buffer.from(xml, 'utf-8');
return [{ json: { success: true }, binary: { data: { data: buffer.toString('base64'), mimeType: 'application/vnd.ms-excel', fileName: 'tabla_excell_facturas.xls', fileExtension: 'xls' } } }];
